namespace YouthDataManager.Infrastructure.Data;

public class AppDbContext : IdentityDbContext<ApplicationUser, IdentityRole<Guid>, Guid>, IUnitOfWork
{
    private readonly ICallerContext? _caller;
    public bool HasServiceYear => _caller?.SelectedServiceYear != null;
    public DateTime ServiceYearStart => _caller?.SelectedServiceYear?.UtcStart ?? DateTime.MinValue;
    public DateTime ServiceYearEnd => _caller?.SelectedServiceYear?.UtcEnd ?? DateTime.MaxValue;
    public DateTime ServiceYearFirstDate => _caller?.SelectedServiceYear?.Start ?? DateTime.MinValue;
    public DateTime ServiceYearNextDate => _caller?.SelectedServiceYear?.LastDay.AddDays(1) ?? DateTime.MaxValue;
    public CancellationToken RequestCancellation => _caller?.CancellationToken ?? default;
    public AppDbContext(DbContextOptions<AppDbContext> options, ICallerContext? caller = null)
        : base(options)
    {
        _caller = caller;
    }

    public DbSet<Student> Students => Set<Student>();
    public DbSet<CallLog> CallLogs => Set<CallLog>();
    public DbSet<HomeVisit> HomeVisits => Set<HomeVisit>();
    public DbSet<HomeVisitParticipant> HomeVisitParticipants => Set<HomeVisitParticipant>();
    public DbSet<ActivityLog> ActivityLogs => Set<ActivityLog>();
    public DbSet<StudentRemovalRequest> StudentRemovalRequests => Set<StudentRemovalRequest>();
    public DbSet<StudentAssignmentRequest> StudentAssignmentRequests => Set<StudentAssignmentRequest>();
    public DbSet<StudentAdditionRequest> StudentAdditionRequests => Set<StudentAdditionRequest>();
    public DbSet<StudentAttendance> StudentAttendances => Set<StudentAttendance>();
    public DbSet<ServantAttendance> ServantAttendances => Set<ServantAttendance>();
    public DbSet<StudentEditLog> StudentEditLogs => Set<StudentEditLog>();
    public DbSet<NotificationSchedule> NotificationSchedules => Set<NotificationSchedule>();
    public DbSet<UserDeviceToken> UserDeviceTokens => Set<UserDeviceToken>();

