    public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        if(cancellationToken==default)cancellationToken=RequestCancellation;
        cancellationToken.ThrowIfCancellationRequested();
        ChangeTracker.DetectChanges();
        var audited = new HashSet<string> { nameof(Student),nameof(ApplicationUser),nameof(CallLog),nameof(HomeVisit),nameof(StudentAdditionRequest),nameof(StudentAssignmentRequest),nameof(StudentRemovalRequest),nameof(FollowUpTask),nameof(MeetingSession),nameof(MeetingRosterEntry),nameof(MeetingConfiguration),nameof(NotificationDelivery) };
        var sensitive = new HashSet<string> { "PasswordHash","SecurityStamp","ConcurrencyStamp","Version" };
        var entries = ChangeTracker.Entries().Where(e => audited.Contains(e.Entity.GetType().Name) && e.State is EntityState.Added or EntityState.Modified or EntityState.Deleted).ToList();
        foreach (var entry in entries)
        {
            var properties = entry.Properties.Where(p => !sensitive.Contains(p.Metadata.Name) && (entry.State != EntityState.Modified || p.IsModified)).ToList();
            Set<AuditEntry>().Add(new AuditEntry {
                ActorId = _caller?.UserId, EntityType = entry.Entity.GetType().Name,
                EntityId = entry.Property("Id").CurrentValue?.ToString() ?? "",
                Action = entry.State.ToString(), Reason = _caller?.Reason,
                CorrelationId = _caller?.CorrelationId ?? "background",
                BeforeJson = JsonSerializer.Serialize(properties.ToDictionary(p => p.Metadata.Name,p => entry.State == EntityState.Added ? null : p.OriginalValue)),
                AfterJson = JsonSerializer.Serialize(properties.ToDictionary(p => p.Metadata.Name,p => entry.State == EntityState.Deleted ? null : p.CurrentValue))
            });
        }
        // Request notifications are saved atomically with business state and structured audit.
        var changedRequests=entries.Where(e=>e.Entity is StudentAdditionRequest or StudentAssignmentRequest or StudentRemovalRequest)
            .Where(e=>e.State==EntityState.Added || e.Property("Status").IsModified).ToList();
        if(changedRequests.Count>0)
        {
            var roleIds=Roles.Where(r=>r.Name=="Admin" || r.Name=="Manager" || r.Name=="Priest").Select(r=>r.Id);
            var processors=await Users.Where(u=>u.IsActive && UserRoles.Any(r=>r.UserId==u.Id && roleIds.Contains(r.RoleId))).Select(u=>u.Id).ToListAsync(cancellationToken);
            var requesterIds=changedRequests.Select(e=>(Guid)e.Property("RequestedByUserId").CurrentValue!).Distinct().ToArray();
            var activeRequesters=await Users.Where(u=>u.IsActive && requesterIds.Contains(u.Id)).Select(u=>u.Id).ToListAsync(cancellationToken);
            foreach(var request in changedRequests)
            {
                var status=request.Property("Status").CurrentValue!.ToString();
                var id=(Guid)request.Property("Id").CurrentValue!;var requester=(Guid)request.Property("RequestedByUserId").CurrentValue!;
                var recipients=status=="Pending" ? processors : activeRequesters.Where(u=>u==requester).ToList();
                foreach(var user in recipients)
                {
                    var key=$"request:{request.Entity.GetType().Name}:{id}:{status}:{user}";
                    if(!Set<NotificationDelivery>().Local.Any(n=>n.OccurrenceKey==key) && !await Set<NotificationDelivery>().AnyAsync(n=>n.OccurrenceKey==key,cancellationToken))
                        Set<NotificationDelivery>().Add(new(){UserId=user,AppType=status=="Pending" ? "Admin" : "Any",OccurrenceKey=key,
                            Title=status=="Pending" ? "طلب جديد يحتاج مراجعة" : "تحديث حالة طلبك",Body=$"حالة الطلب: {status switch {"Approved"=>"مقبول","Rejected"=>"مرفوض","Cancelled"=>"ملغى",_=>"قيد الانتظار"}}"});
                }
            }
        }
        return await base.SaveChangesAsync(cancellationToken);
    }
